// ============================================================================
// ipcam_soc_timer_wdt_regs -- APB4 register file generated by socgen from
// register_blocks.timer_wdt in socgen/specs/ipcam_soc.yaml. System timer and watchdog
//  - zero wait states, 32-bit data, 12-bit byte address, PSTRB byte lanes
//  - PSLVERR on an unmapped or misaligned offset
//  - hw_* inputs: values of RO registers and set pulses of W1C bits (from the
//    block's logic; tie to 0 for a register-only model)
// ============================================================================
module ipcam_soc_timer_wdt_regs (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  input  logic [31:0] hw_value,
  input  logic [31:0] hw_irq_status,
  output logic [31:0] q_ctrl,
  output logic [31:0] q_load,
  output logic [31:0] q_wdt_load,
  output logic [31:0] q_wdt_kick,
  output logic        we_wdt_kick
);
  wire        acc   = PSEL & PENABLE;
  wire        wr    = acc & PWRITE;
  wire [31:0] wmask = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic       hit;
  always_comb begin
    hit = 1'b0;
    case (PADDR)
      12'h000: hit = 1'b1;
      12'h004: hit = 1'b1;
      12'h008: hit = 1'b1;
      12'h00C: hit = 1'b1;
      12'h010: hit = 1'b1;
      12'h014: hit = 1'b1;
      12'h018: hit = 1'b1;
      default: hit = 1'b0;
    endcase
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~hit;

  // 000 ID RO reset 0x54570100: code 0x5457 ('TW'), version 1.0
  // 004 CTRL RW reset 0x00000000
  logic [31:0] r_ctrl;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_ctrl <= 32'h00000000;
    else if (wr && PADDR == 12'h004)
      r_ctrl <= ((r_ctrl & ~wmask) | (PWDATA & wmask)) & 32'h00000007;
  assign q_ctrl = r_ctrl;
  // 008 LOAD RW reset 0x00000000
  logic [31:0] r_load;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_load <= 32'h00000000;
    else if (wr && PADDR == 12'h008)
      r_load <= ((r_load & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_load = r_load;
  // 00C VALUE RO reset 0x00000000
  // 010 WDT_LOAD RW reset 0xFFFFFFFF
  logic [31:0] r_wdt_load;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_wdt_load <= 32'hFFFFFFFF;
    else if (wr && PADDR == 12'h010)
      r_wdt_load <= ((r_wdt_load & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_wdt_load = r_wdt_load;
  // 014 WDT_KICK WO reset 0x00000000
  logic [31:0] r_wdt_kick;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_wdt_kick <= 32'h00000000;
    else if (wr && PADDR == 12'h014)
      r_wdt_kick <= ((r_wdt_kick & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_wdt_kick = r_wdt_kick;
  assign we_wdt_kick = wr && PADDR == 12'h014;
  // 018 IRQ_STATUS W1C reset 0x00000000
  logic [31:0] r_irq_status;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_irq_status <= 32'h00000000;
    else r_irq_status <= ((r_irq_status & ~((wr && PADDR == 12'h018) ? (PWDATA & wmask) : 32'h0))
                         | hw_irq_status) & 32'h00000003;

  always_comb begin
    PRDATA = 32'h0;
    if (acc && !PWRITE)
      case (PADDR)
        12'h000: PRDATA = 32'h54570100;
        12'h004: PRDATA = r_ctrl;
        12'h008: PRDATA = r_load;
        12'h00C: PRDATA = hw_value & 32'hFFFFFFFF;
        12'h010: PRDATA = r_wdt_load;
        12'h014: PRDATA = 32'h0;
        12'h018: PRDATA = r_irq_status;
        default: PRDATA = 32'h0;
      endcase
  end
endmodule
